rule_yaml:
rules:
  - id: dubbo-npe-c1-r2
    languages:
      - java
    severity: ERROR
    message: >-
      A possibly-null value is used without a null guard: the URL component field 'urlAddress' (left null by the no-arg constructor chain URL() / ServiceConfigURL() / URLBuilder()), the result of a nullable service-info lookup (getServiceInfo() / getValidServiceInfo(), which return null when no matching ServiceInfo exists), or the result of a nullable invocation-attachment lookup (getObjectAttachmentWithoutConvert() / getObjectAttachment() / getAttachments().get()). The unguarded dereference, or use of the value as a service key / method argument, throws a NullPointerException. Guard the value before using it, e.g. if (x == null) return ...; / if (x == null) throw ...; / if (x != null) { ... } / x == null ? ... : x.method().
    paths:
      exclude:
        - "**/src/test/**"
        - "**/test/**"
    patterns:
      - pattern-either:
          - pattern: getServiceInfo(...).$M(...)
          - pattern: getValidServiceInfo(...).$M(...)
          - patterns:
              - pattern-inside: |
                  $TYPE $SI = $LOOKUP(...);
                  ...
              - metavariable-regex:
                  metavariable: $LOOKUP
                  regex: "(getServiceInfo|getValidServiceInfo)$"
              - pattern: $SI.$M(...)
              - pattern-not-inside: |
                  if ($SI == null) {
                      ...
                  }
              - pattern-not-inside: |
                  if (null == $SI) {
                      ...
                  }
              - pattern-not-inside: |
                  if ($SI != null) {
                      ...
                  }
              - pattern-not-inside: |
                  if (null != $SI) {
                      ...
                  }
              - pattern-not-inside: |
                  if ($SI == null) return $X;
                  ...
              - pattern-not-inside: |
                  if (null == $SI) return $X;
                  ...
              - pattern-not-inside: |
                  $SI == null ? $A : $SI.$M(...)
              - pattern-not-inside: |
                  null == $SI ? $A : $SI.$M(...)
              - pattern-not-inside: |
                  $SI != null ? $SI.$M(...) : $A
              - pattern-not-inside: |
                  null != $SI ? $SI.$M(...) : $A
          - patterns:
              - pattern-either:
                  - pattern: |
                      $T $V = urlAddress.$M(...);
                      return $R($V);
                  - pattern: |
                      return urlAddress.$M(...);
              - pattern-not-inside: |
                  if (urlAddress == null) {
                      ...
                  }
              - pattern-not-inside: |
                  if (urlAddress != null) {
                      ...
                  }
              - pattern-not-inside: |
                  urlAddress == null ? $A : $B
              - pattern-not-inside: |
                  urlAddress != null ? $A : $B
              - pattern-not-inside: |
                  if (...) {
                      ...
                  }
          - patterns:
              - pattern-inside: |
                  $T $PATH = $SRC;
                  ...
              - metavariable-regex:
                  metavariable: $SRC
                  regex: (?is).*attachment.*
              - pattern-either:
                  - pattern: $PATH.$M(...)
                  - pattern: $F(..., $PATH, ...)
              - pattern-not-inside: |
                  $RET $METHOD(...) {
                    ...
                    if ($PATH == null) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $METHOD(...) {
                    ...
                    if (null == $PATH) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $METHOD(...) {
                    ...
                    if ($PATH != null) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $METHOD(...) {
                    ...
                    if (null != $PATH) {
                      ...
                    }
                    ...
                  }
              - pattern-not-inside: |
                  $RET $METHOD(...) {
                    ...
                    if ($PATH == null) return $X;
                    ...
                  }
